<script setup lang="ts">
import { ref,onMounted } from 'vue';import { request } from '../crm-api';
const props=defineProps<{locale:string}>();const tx=(z:string,e:string)=>props.locale==='zh'?z:e;
const data=ref({ai:{configured:false,model:'gpt-5'},smtp:{configured:false,sender:''},imap:{configured:false},webhook:{configured:false}}),notice=ref(''),busy=ref(false);
onMounted(async()=>{try{data.value=await request('integrations/status')}catch{notice.value=tx('暂时无法读取服务配置','Could not load service settings')}});
async function sync(){busy.value=true;try{const result=await request<{received:number}>('mail/sync',{});notice.value=tx('已归档'+result.received+'封新邮件。','Archived '+result.received+' new messages.')}catch{notice.value=tx('收件连接未成功，请核对服务器邮箱配置。','Mailbox connection failed. Review the server-side settings.')}finally{busy.value=false}}
</script>
<template><section class="integration-status"><h2>{{tx('邮件与AI服务','Mail & AI services')}}</h2><p>{{tx('配置在服务器.env中管理，密钥不显示在页面。接入后，邮件归档、摘要与跟进事项自动处理。','Settings are managed in the server environment. Keys are never shown here. Once connected, archiving and analysis run automatically.')}}</p><div class="integration-grid"><article><span>{{tx('文本模型','LANGUAGE MODEL')}}</span><h3>GPT-5</h3><small :class="{ready:data.ai.configured}">{{data.ai.configured?tx('已配置','Configured'):tx('待配置密钥','API key required')}}</small><p>{{tx('自动摘要、需求提取与邮件正文。','Summaries, requirement extraction and email drafting.')}}</p></article><article><span>{{tx('发件服务','OUTGOING MAIL')}}</span><h3>SMTP</h3><small :class="{ready:data.smtp.configured}">{{data.smtp.configured?tx('已配置','Configured'):tx('待配置邮箱','Mailbox required')}}</small><p>{{data.smtp.sender||tx('发送后自动归档，无需重复记录。','Automatically archived after sending.')}}</p></article><article><span>{{tx('收件服务','INCOMING MAIL')}}</span><h3>IMAP</h3><small :class="{ready:data.imap.configured}">{{data.imap.configured?tx('已配置','Configured'):tx('待配置邮箱','Mailbox required')}}</small><p>{{tx('按邮件线程关联项目并自动整理。','Link replies to projects and process them automatically.')}}</p></article></div><footer><button type="button" :disabled="busy||!data.imap.configured" @click="sync">{{busy?tx('检查中…','Checking…'):tx('检查收件连接','Check receiving connection')}}</button><span>{{notice}}</span></footer></section></template>
<style scoped>
.integration-status{padding:20px 0 36px;border-bottom:1px solid #e1e8dd;margin-bottom:28px}.integration-status h2{font-size:24px;font-weight:500;margin:0 0 14px}.integration-status>p{max-width:620px;font-size:13px;line-height:1.8;color:#829177}.integration-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:28px 0 22px}.integration-grid article{padding:22px;border:1px solid #e0e8d9;background:#fff;border-radius:6px}.integration-grid article>span{font-size:10px;letter-spacing:.08em;color:#89977f}.integration-grid h3{font-size:22px;font-weight:500;margin:18px 0 12px}.integration-grid small{font-size:11px;color:#a28e6f}.integration-grid small.ready{color:#0f6e5c}.integration-grid p{font-size:11px;line-height:1.8;color:#89977f;margin:16px 0 0}.integration-status footer{display:flex;align-items:center;gap:16px}.integration-status button{border:1px solid #d1ddc7;background:#fff;color:#506f42;border-radius:4px;padding:10px 15px;font:12px var(--font-body);cursor:pointer}.integration-status button:disabled{opacity:.5;cursor:default}.integration-status footer span{font-size:12px;color:#72876b}@media(max-width:700px){.integration-grid{grid-template-columns:1fr;gap:10px}.integration-grid article{padding:18px}.integration-grid h3{margin:12px 0;font-size:20px}.integration-status footer{align-items:start;flex-direction:column}}
</style>
